VALUES (179111, 'tt2375574', NULL, 'A Field in England', 'A Field in England', 'movie', 2013, 'https://image.tmdb.org/t/p/w500/dKhMJr8yoHVyvxyUiAeIn2hKVdL.jpg', 'https://image.tmdb.org/t/p/original/euBvKWkvYD38O7dMMvw3GvrkZoa.jpg', 'During the Civil War in 17th-Century England, a small group of deserters flee from a raging battle through an overgrown field. They are captured by an alchemist, who forces the group to aid him in his search to find a hidden treasure that he believes is buried in the field. Crossing a vast mushroom circle, which provides their first meal, the group quickly descend into a chaos of arguments, fighting and paranoia, and, as it becomes clear that the treasure might be something other than gold, they slowly become victim to the terrifying energies trapped inside the field.', NULL, NULL, 1.193, 6.212, 0, 2.31809999999999973e+01, '2026-07-15 12:01:52', '2026-10-15 19:58:42')
