VALUES (11527, 'tt0082348', NULL, 'Excalibur', 'Excalibur', 'movie', 1981, 'https://image.tmdb.org/t/p/w500/cTWF6zkr5mUOnheowKODIijWYcN.jpg', 'https://image.tmdb.org/t/p/original/mrabn7LREC8HOBBUyQIXZsQvWk3.jpg', 'Arthur fulfills his fate by bringing together the Knights of the Round Table at Camelot and unifying the country. However, this flawed monarch faces greater tests ahead in pursuit of love, the Holy Grail, and his nation''s survival.', NULL, NULL, 5.3152, 7.0, 0, 9.763473118279569e+01, '2026-07-15 12:01:52', '2026-10-15 19:58:42')
