VALUES (12159, 'tt0120889', NULL, 'What Dreams May Come', 'What Dreams May Come', 'movie', 1998, 'https://image.tmdb.org/t/p/w500/78wCdphUzeb528wLZw2W0fn7yGB.jpg', 'https://image.tmdb.org/t/p/original/586n41CjDveXtwmQgP41YtyHKUV.jpg', 'Chris Nielsen dies to find himself in a heaven more amazing than he could have ever dreamed of. There is one thing missing: his wife. After he died, his wife Annie killed herself and went to hell. Chris decides to risk eternity in Hades for the small chance that he will be able to bring her back to heaven.', NULL, NULL, 4.9619, 7.241, 0, 9.8827473684210517e+01, '2026-07-15 12:01:52', '2026-10-15 19:58:42')
