VALUES (31917, 'tt1578873', NULL, 'Pretty Little Liars', 'Pretty Little Liars', 'tv', 2010, 'https://image.tmdb.org/t/p/w500/aUPbHiLS3hCHKjtLsncFa9g0viV.jpg', 'https://image.tmdb.org/t/p/original/hunaEPitjdWsJgqmiIBglySNClr.jpg', 'Based on the Pretty Little Liars series of young adult novels by Sara Shepard, the series follows the lives of four girls — Spencer, Hanna, Aria, and Emily — whose clique falls apart after the disappearance of their queen bee, Alison. One year later, they begin receiving messages from someone using the name "A" who threatens to expose their secrets — including long-hidden ones they thought only Alison knew.', NULL, NULL, 44.1138, 8.0, 0, 1.45408333333333334e+01, '2026-07-20 01:02:04', '2026-10-15 19:58:42')
