VALUES (60905, 'tt2963254', NULL, 'Salem', 'Salem', 'tv', 2014, 'https://image.tmdb.org/t/p/w500/sS9pnQSjH2COeBvhRalfyZlN4TJ.jpg', 'https://image.tmdb.org/t/p/original/f1sjJoT21vH9snaCjipKlMM1DCF.jpg', 'Set in the volatile world of 17th century Massachusetts, ''Salem'' explores what really fueled the town''s infamous witch trials and dares to uncover the dark, supernatural truth hiding behind the veil of this infamous period in American history. In Salem, witches are real, but they are not who or what they seem.', NULL, NULL, 30.5356, 7.316, 0, 6.255, '2026-07-20 04:02:06', '2026-10-15 19:58:42')
